def transform(grid):
    from collections import Counter
    counts = Counter()
    for row in grid:
        counts.update(row)
    # Identify background color (most frequent)
    bg_color = max(counts, key=counts.get)

    # Identify frame color (most frequent non-background)
    structure_color = None
    max_struct = 0
    for c in range(10):
        if counts[c] > max_struct and c != bg_color:
            max_struct = counts[c]
            structure_color = c

    if structure_color is None:
        return grid

    h, w = len(grid), len(grid[0])
    r_min, r_max = h, -1
    c_min, c_max = w, -1

    # Find bounding box of the frame color
    for r in range(h):
        for c in range(w):
            if grid[r][c] == structure_color:
                r_min = min(r_min, r)
                r_max = max(r_max, r)
                c_min = min(c_min, c)
                c_max = max(c_max, c)

    result = [row[:] for row in grid]

    # Fill the interior of the bounding box with 4
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            if result[r][c] != structure_color:
                result[r][c] = 4

    return result
